from lib import *
S = SS('x38')
steps = [
    step("@TransactionalEventListener 各个 phase 什么时候收到事件。事务正常提交:普通 @EventListener 在 publishEvent 时立刻收到(第 2 条,事务还没提交);publishEvent 返回之后才有 BEFORE_COMMIT(第 4 条)、AFTER_COMMIT(fallbackExecution = true 的那个,第 5 条)、AFTER_COMPLETION(第 6 条)、AFTER_COMMIT(第 7 条)。事务回滚:普通监听器照样收到,AFTER_ROLLBACK 和 AFTER_COMPLETION 收到,BEFORE_COMMIT 和 AFTER_COMMIT 都没有,调用者收到 IllegalStateException。没有事务时直接 publishEvent:只有 fallbackExecution = true 的 AFTER_COMMIT 监听器和普通监听器收到,别的事务监听器默认被丢弃。同一次提交里几个监听器的先后我没有找到规律(上面是这次运行的顺序)。", t=tl(S(1)), mark=lidx(S(1), '[AFTER_ROLLBACK] 收到 2', '没有事务时直接 publishEvent'), done=lidx(S(1), '[BEFORE_COMMIT] 收到 1', '[AFTER_COMMIT] 收到 1', '[普通 @EventListener] 收到 1'), b=bars([['正常提交时收到事件的监听器', 5, '5(除 AFTER_ROLLBACK)'], ['回滚时收到事件的监听器', 3, '3(普通、AFTER_ROLLBACK、AFTER_COMPLETION)'], ['没有事务时收到事件的监听器', 2, '2(普通、fallbackExecution)']], 5, done=[0], mark=[1], cur=[2]), kv=KV([['普通 @EventListener', 'publishEvent 时立即执行(事务还没提交)'], ['BEFORE_COMMIT / AFTER_COMMIT', '只在提交时'], ['回滚', 'AFTER_ROLLBACK 与 AFTER_COMPLETION'], ['没有事务', '默认丢弃,fallbackExecution = true 才执行']], ['没有事务'])),
    step("AFTER_COMMIT 监听器里的数据库写入。三个监听器各插一行 audit:没有 @Transactional 的、@Transactional(REQUIRES_NEW) 的、@Transactional(NOT_SUPPORTED) 的,事务提交之后 audit 表里有 [REQUIRES_NEW, NOT_SUPPORTED, PLAIN],三行都在。另外试一个 @Transactional(REQUIRED) 的监听器:Spring 7.0.9 启动就失败:IllegalStateException:@TransactionalEventListener method must not be annotated with @Transactional unless when declared as REQUIRES_NEW or NOT_SUPPORTED。框架在启动时就把“提交之后又加入已经结束的事务”这种写法拦掉了。", t=tl(S(2)), mark=lidx(S(2), '启动失败'), done=lidx(S(2), 'audit 表里有'), b=bars([['没有 @Transactional / REQUIRES_NEW / NOT_SUPPORTED 的写入成功行数', 3, '3'], ['@Transactional(REQUIRED) 的监听器能启动', 0, '不能(启动失败)']], 3, done=[0], mark=[1]), kv=KV([['REQUIRES_NEW / NOT_SUPPORTED', '允许,写入成功'], ['没有 @Transactional', '这次写入也成功了'], ['REQUIRED', '启动时 IllegalStateException'], ['原因', '提交之后不能再加入那个已经结束的事务']], ['REQUIRED'])),
    step("异步监听器能不能读到刚下的订单。在事务里 publishEvent,监听器用 @Async 在另一个线程里用自己的连接查这个订单,100 次下单。@Async @EventListener(事件在事务里发布):监听器被调用 100 次,其中读得到订单的只有 90 次,另外 10 次在事务提交之前就读了,读不到。@Async @TransactionalEventListener(AFTER_COMMIT):100 次全部读得到。提交之后再异步处理,要用 @TransactionalEventListener,不能只靠 @Async。", t=tl(S(3)), mark=lidx(S(3), '@Async @EventListener(事件在事务里发布)'), done=lidx(S(3), '@Async @TransactionalEventListener(AFTER_COMMIT)'), b=bars([['@Async @EventListener:读得到订单', 90, '90(共 100)'], ['@Async @TransactionalEventListener:读得到订单', 100, '100(共 100)']], 100, mark=[0], done=[1]), kv=KV([['@Async @EventListener', '90 次读得到,10 次读不到(竞争提交)'], ['@Async @TransactionalEventListener(AFTER_COMMIT)', '100 次读得到'], ['原因', '事件在事务里发布,异步线程可能在提交之前就开始'], ['每次运行', '读不到的次数会不同(开发中另一次是 16)']], ['原因'])),
    step("AFTER_COMMIT 监听器抛异常。place() 照常返回,调用者没有收到异常,表 orders 里有 1 行(事务已经提交);异常被记成一条 ERROR 日志:TransactionSynchronizationUtils:TransactionSynchronization.afterCompletion threw exception。AFTER_COMMIT 监听器出错不会影响调用者,也撤销不了提交,只会留在日志里。", t=tl(S(4)), mark=lidx(S(4), 'place() 正常返回', '表 orders 里有 1 行'), done=lidx(S(4), 'LOG ERROR TransactionSynchronizationUtils'), b=bars([['调用者收到异常', 0, '否'], ['订单已提交的行数', 1, '1'], ['ERROR 日志条数', 1, '1']], 1, mark=[0], done=[1, 2]), kv=KV([['调用者', '正常返回'], ['数据库', '订单已经提交'], ['异常去向', 'ERROR 日志:afterCompletion threw exception'], ['建议', '监听器里自己做好重试与告警']], ['异常去向'])),
]
A = mkartx('x38', 38, 'Spring,事务,TransactionalEventListener,AFTER_COMMIT,事务事件,真实验证,动画演示',
    '实测 @TransactionalEventListener:普通 @EventListener 在事务里立刻执行,AFTER_COMMIT 在提交之后,回滚时收到 AFTER_ROLLBACK;@Transactional(REQUIRED) 的 AFTER_COMMIT 监听器在 Spring 7.0.9 启动时就被拒绝;@Async @EventListener 有 10% 读不到刚提交的订单(90/100),换成 AFTER_COMMIT 是 100/100;AFTER_COMMIT 监听器抛异常只记日志、不传给调用者。',
    '想在事务提交之后再发消息、写审计、清缓存,该用什么?@EventListener 加 @Async 为什么会读不到刚下的订单?AFTER_COMMIT 里还能写数据库吗?监听器失败了调用者知道吗?这篇在 Spring Framework 7.0.9 和 MySQL 26.7.0 上逐项验证。',
    [('90 对 100', '事务里 publishEvent、@Async @EventListener 监听器读得到刚下订单的次数,与 AFTER_COMMIT 的 100 次对比(各 100 次下单)'), ('启动失败', '@Transactional(REQUIRED) 的 @TransactionalEventListener 方法在 Spring 7.0.9 里的表现'), ('不传给调用者', 'AFTER_COMMIT 监听器抛的异常只记 ERROR 日志')],
    [('各阶段', '<p>普通监听器立即执行,事务监听器在 BEFORE_COMMIT、AFTER_COMMIT、AFTER_ROLLBACK、AFTER_COMPLETION 阶段执行;没有事务默认丢弃。</p>'),
     ('监听器里写库', '<p>REQUIRES_NEW 与 NOT_SUPPORTED 可以,REQUIRED 启动就被拒绝。</p>'),
     ('异步监听', '<p>提交之后再异步处理要用 AFTER_COMMIT,否则可能读不到刚提交的数据。</p>'),
     ('监听器失败', '<p>AFTER_COMMIT 监听器的异常只记日志,调用者不知道。</p>')],
    steps,
    [ENV_X + '。用不带 Boot 的 Spring Framework 7.0.9 + @EnableAsync + DataSourceTransactionManager + HikariCP(连接池 10)+ 自己起的 MySQL 26.7.0;第三节的 90 次是这次运行的结果,每次运行不同(开发中另一次是 84 次);同一个提交里各监听器的先后顺序我没有找到规律,只记录了这次的顺序',
     '没有验证:@TransactionalEventListener 配合 @Order 的顺序;事务内发布多个事件的顺序;响应式事务的事件;Outbox 表方案(见后面的 Outbox 篇);Spring 6.1 之前同一个场景下 REQUIRED 监听器的静默丢失行为(这篇只验证了 7.0.9 在启动时就拒绝);AFTER_COMMIT 监听器执行时 afterCommit 与 afterCompletion 的具体回调点'],
    '提交之后再做事')
